package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_2 : Integer;
    in attribute io_2_valid : Boolean;
    attribute lastServoAngleDeg : Integer := 0;
    perform action tick {
      first start;
      then if true {
        first start;
        then assign lastServoAngleDeg := (if io_0 <= 0.0 ? 0 else (if io_0 >= 1023.0 ? 180 else RealFunctions::floor(io_0 * 180.0 / 1023.0)));
      }
      then if io_2_valid {
        first start;
        then done;
      }
    }
    out attribute io_1 : Real = lastServoAngleDeg;
    out attribute serial_0_trigger : Boolean = true;
    out attribute serial_0_value_0 : Integer = lastServoAngleDeg;
  }
  part system : Controller;
}
